        let rel = center - cs.params0.xyz;
        let t = dot(rel, cs.params1.xyz);
        let radial = rel - t * cs.params1.xyz;
        let rr = cs.params0.w - radius;
        entirely_inside = rr > 0.0 && t >= radius && t <= cs.params1.w - radius &&
                          dot(radial, radial) < rr * rr;
