      let gx = ld_depth(xy, vec2i(1, 0), dims, s) - d_c;
      let gy = ld_depth(xy, vec2i(0, 1), dims, s) - d_c;
      let depth_edge = 4.0 * sqrt(gx * gx + gy * gy);
